// The port of verify.ts. Written without template literals so the generator can
// embed it without escaping games.
const APP = `
(function () {
  "use strict";
  var enc = new TextEncoder();
  var sha3_512 = globalThis.EGVendor.sha3_512;
  var nobleVerify = globalThis.EGVendor.ed25519Verify;
  var edPath = "";

  function sha3Bytes(x) { return sha3_512(typeof x === "string" ? enc.encode(x) : x); }
  function toHex(b) {
    var s = "";
    for (var i = 0; i < b.length; i++) s += b[i].toString(16).padStart(2, "0");
    return s;
  }
  function sha3Hex(x) { return toHex(sha3Bytes(x)); }
  function fingerprint(pub) { return sha3Hex(pub).slice(0, 16); }

  function fromB64u(s) {
    var b64 = String(s).replace(/-/g, "+").replace(/_/g, "/");
    var pad = (4 - (b64.length % 4)) % 4;
    var bin = atob(b64 + "=".repeat(pad));
    var out = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }

  // Port of packages/gate/src/jcs.ts. Identical output or nothing verifies.
  function jcs(v) {
    if (v === null) return "null";
    var t = typeof v;
    if (t === "number") {
      if (!Number.isFinite(v)) throw new Error("cannot canonicalize a non-finite number");
      return JSON.stringify(v);
    }
    if (t === "boolean" || t === "string") return JSON.stringify(v);
    if (t === "bigint") throw new Error("cannot canonicalize a bigint");
    if (t === "undefined" || t === "function" || t === "symbol") {
      throw new Error("cannot canonicalize a value of type " + t);
    }
    if (Array.isArray(v)) {
      return "[" + v.map(function (x) { return jcs(x === undefined ? null : x); }).join(",") + "]";
    }
    var keys = Object.keys(v).sort();
    var parts = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (v[k] === undefined) continue;
      parts.push(JSON.stringify(k) + ":" + jcs(v[k]));
    }
    return "{" + parts.join(",") + "}";
  }

  // WebCrypto Ed25519 where the browser has it, inlined @noble where it does
  // not. A failed verification returns false from SubtleCrypto; only a missing
  // algorithm throws on importKey, which is what switches the path.
  async function edVerify(pub, msg, sig) {
    if (edPath !== "inlined @noble") {
      try {
        var key = await crypto.subtle.importKey("raw", pub, { name: "Ed25519" }, false, ["verify"]);
        var ok = await crypto.subtle.verify("Ed25519", key, sig, msg);
        edPath = "WebCrypto";
        return ok;
      } catch (e) {
        edPath = "inlined @noble";
      }
    }
    return nobleVerify(sig, msg, pub);
  }

  async function verifyReceiptText(text, publicKeyB64u) {
    var pub;
    try {
      pub = fromB64u(publicKeyB64u);
    } catch (e) {
      return { ok: false, total: 0, allows: 0, denies: 0,
               breaks: [{ line: 0, kind: "key", issue: "public key is not valid base64url" }] };
    }
    if (pub.length !== 32) {
      return { ok: false, total: 0, allows: 0, denies: 0,
               breaks: [{ line: 0, kind: "key",
                          issue: "public key must be 32 bytes, got " + pub.length }] };
    }

    var lines = text.split("\\n").map(function (l) { return l.trim(); })
                    .filter(function (l) { return l.length > 0; });
    var singleKeyKid = fingerprint(pub);
    var breaks = [];
    var allows = 0, denies = 0;
    var prevHash = "genesis";

    for (var idx = 0; idx < lines.length; idx++) {
      var ln = idx + 1;
      var r;
      try {
        r = JSON.parse(lines[idx]);
      } catch (e) {
        breaks.push({ line: ln, kind: "json", issue: "invalid JSON" });
        continue; // prevHash is NOT advanced, matching verify.ts
      }

      if (r.prevReceiptHash !== prevHash) {
        breaks.push({ line: ln, kind: "chain",
                      issue: "chain break: prevReceiptHash does not match the previous receipt" });
      }

      if (r.kid !== singleKeyKid) {
        breaks.push({ line: ln, kind: "kid",
                      issue: "kid " + r.kid + " does not match the provided public key (" +
                             singleKeyKid + ")" });
      } else {
        var unsigned = {};
        for (var k in r) if (k !== "sig") unsigned[k] = r[k];
        var sigOk = false;
        try {
          sigOk = await edVerify(pub, sha3Bytes(jcs(unsigned)), fromB64u(r.sig));
        } catch (e) {
          sigOk = false;
        }
        if (!sigOk) breaks.push({ line: ln, kind: "signature", issue: "signature invalid" });
      }

      if (r.decision === "allow") allows++;
      else if (r.decision === "deny") denies++;
      else breaks.push({ line: ln, kind: "decision",
                         issue: "unknown decision value: " + String(r.decision) });

      prevHash = sha3Hex(jcs(r));
    }

    return { ok: breaks.length === 0, total: lines.length, allows: allows, denies: denies,
             breaks: breaks };
  }

  var EXAMPLES = __EXAMPLES__;
  var $ = function (id) { return document.getElementById(id); };

  function render(report) {
    $("result").hidden = false;
    var verdict = $("verdict");
    verdict.dataset.verdict = report.ok ? "pass" : "fail";
    verdict.textContent = report.ok
      ? "VERIFIED — " + report.total + " receipts, chain intact, every signature valid"
      : "FAILED — " + report.breaks.length +
        (report.breaks.length === 1 ? " problem found" : " problems found");
    $("summary").textContent =
      "receipts: " + report.total + ", allows: " + report.allows + ", denies: " + report.denies;
    var ul = $("failures");
    ul.textContent = "";
    report.breaks.forEach(function (b) {
      var li = document.createElement("li");
      li.className = "failure";
      li.dataset.kind = b.kind;
      li.dataset.line = String(b.line);
      var span = document.createElement("span");
      span.className = "line";
      span.textContent = "line " + b.line + ": ";
      li.appendChild(span);
      li.appendChild(document.createTextNode(b.issue));
      ul.appendChild(li);
    });
    $("crypto-path").textContent = edPath || "not run yet";
  }

  async function run() {
    var btn = $("verify");
    btn.disabled = true;
    try {
      render(await verifyReceiptText($("receipts").value, $("pubkey").value.trim()));
    } finally {
      btn.disabled = false;
    }
  }

  function loadExample(which) {
    $("pubkey").value = EXAMPLES.publicKey;
    $("receipts").value = EXAMPLES[which];
    return run();
  }

  $("verify").addEventListener("click", run);
  $("example-signed").addEventListener("click", function () { return loadExample("signed"); });
  $("example-tampered").addEventListener("click", function () { return loadExample("tampered"); });
})();
`;

const [vendor, examples] = await Promise.all([vendorBundle(), makeExamples()]);

const html = PAGE.replace("__CSS__", CSS.trim())
  .replace("__VENDOR__", vendor.trim())
  .replace("__APP__", APP.replace("__EXAMPLES__", JSON.stringify(examples)).trim());

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, html);
console.log(
  "docs/verify/index.html: " +
    Math.round(html.length / 1024) +
    " kB, " +
    examples.signed.split("\n").length +
    " receipts per example, kid " +
    examples.publicKey.slice(0, 12) +
    "…",
);
